const dns = require('dns').promises;

const rows = items.map(i => i.json);

function resolveMxComTimeout(domain, timeoutMs = 4000) {
  return Promise.race([
    dns.resolveMx(domain).then((r) => Array.isArray(r) && r.length > 0),
    new Promise((resolve) => setTimeout(() => resolve(false), timeoutMs)),
  ]).catch(() => false);
}

function normalizeEmail(raw) {
  if (!raw) return null;
  let e = String(raw).trim().toLowerCase();
  const m = e.match(/^([^@\s]+)@([^@\s]+)$/);
  if (!m) return null;
  let [, local, domain] = m;
  local = local.replace(/\+.*$/, '');
  if (!local || !domain || !domain.includes('.')) return null;
  if (!/^[a-z0-9._%-]+$/.test(local)) return null;
  if (!/^[a-z0-9.-]+$/.test(domain)) return null;
  return `${local}@${domain}`;
}

function normalizePhone(raw) {
  if (!raw) return null;
  let digits = String(raw).replace(/\D/g, '');
  digits = digits.replace(/^0+/, '');
  if (!digits.startsWith('55')) {
    digits = '55' + digits;
  }
  const national = digits.slice(2);
  // celular BR: DDD (2 dig) + 9 + 8 digitos = 11 digitos nacionais
  if (national.length !== 11) return null;
  if (national[2] !== '9') return null;
  return `+${digits}`;
}

function completeness(row) {
  return ['nome', 'grupo', 'empresa', 'cidade', 'estado', 'pais', 'telefone', 'email',
          'categoria', 'especialidade', 'especialidade_detalhada']
    .reduce((n, k) => n + (row[k] ? 1 : 0), 0);
}

const stats = {
  total_contatos: rows.length,
  email_sintaxe_invalida: 0,
  email_sem_mx: 0,
  email_duplicado: 0,
  email_apto: 0,
  telefone_formato_invalido: 0,
  telefone_duplicado: 0,
  telefone_apto: 0,
};

const byEmail = new Map();
const byPhone = new Map();

for (const row of rows) {
  const emailNorm = normalizeEmail(row.email);
  if (row.email && !emailNorm) stats.email_sintaxe_invalida++;
  if (emailNorm) {
    const existing = byEmail.get(emailNorm);
    if (!existing) {
      byEmail.set(emailNorm, { _raw: row, contato_user_id: row.user_id, email_norm: emailNorm });
    } else if (completeness(row) > completeness(existing._raw)) {
      stats.email_duplicado++;
      byEmail.set(emailNorm, { _raw: row, contato_user_id: row.user_id, email_norm: emailNorm });
    } else {
      stats.email_duplicado++;
    }
  }

  const phoneNorm = normalizePhone(row.telefone);
  if (row.telefone && !phoneNorm) stats.telefone_formato_invalido++;
  if (phoneNorm) {
    const existing = byPhone.get(phoneNorm);
    if (!existing) {
      byPhone.set(phoneNorm, { _raw: row, contato_user_id: row.user_id, telefone_e164: phoneNorm });
    } else if (completeness(row) > completeness(existing._raw)) {
      stats.telefone_duplicado++;
      byPhone.set(phoneNorm, { _raw: row, contato_user_id: row.user_id, telefone_e164: phoneNorm });
    } else {
      stats.telefone_duplicado++;
    }
  }
}

const validacoes = new Map();

function getOrInit(userId) {
  if (!validacoes.has(userId)) {
    validacoes.set(userId, {
      contato_user_id: userId,
      email_norm: null,
      telefone_e164: null,
      email_apto: false,
      whatsapp_apto: false,
      motivo: null,
    });
  }
  return validacoes.get(userId);
}

for (const { contato_user_id, email_norm } of byEmail.values()) {
  getOrInit(contato_user_id).email_norm = email_norm;
}
for (const { contato_user_id, telefone_e164 } of byPhone.values()) {
  getOrInit(contato_user_id).telefone_e164 = telefone_e164;
}

// Rotula quem perdeu a deduplicação (não venceu a disputa pelo email/telefone normalizado)
// para que a linha em contatos_validacao não fique com motivo em branco.
for (const row of rows) {
  const emailNorm = normalizeEmail(row.email);
  if (emailNorm) {
    const winner = byEmail.get(emailNorm);
    if (winner && winner.contato_user_id !== row.user_id) {
      const v = getOrInit(row.user_id);
      v.motivo = v.motivo ? v.motivo + ';duplicado_email' : 'duplicado_email';
    }
  }
  const phoneNorm = normalizePhone(row.telefone);
  if (phoneNorm) {
    const winner = byPhone.get(phoneNorm);
    if (winner && winner.contato_user_id !== row.user_id) {
      const v = getOrInit(row.user_id);
      v.motivo = v.motivo ? v.motivo + ';duplicado_telefone' : 'duplicado_telefone';
    }
  }
}

// Checa MX de todos os domínios únicos em paralelo (lotes de 20), em vez de um por vez —
// com milhares de contatos, checagem sequencial pode levar minutos.
const dominiosUnicos = [...new Set(
  [...validacoes.values()].filter((v) => v.email_norm).map((v) => v.email_norm.split('@')[1])
)];

const CONCORRENCIA = 20;
const mxResultado = new Map();

for (let i = 0; i < dominiosUnicos.length; i += CONCORRENCIA) {
  const lote = dominiosUnicos.slice(i, i + CONCORRENCIA);
  const resultados = await Promise.all(lote.map((d) => resolveMxComTimeout(d)));
  lote.forEach((d, idx) => mxResultado.set(d, resultados[idx]));
}

for (const v of validacoes.values()) {
  if (v.email_norm) {
    const domain = v.email_norm.split('@')[1];
    if (mxResultado.get(domain)) {
      v.email_apto = true;
    } else {
      stats.email_sem_mx++;
      v.motivo = v.motivo ? v.motivo + ';sem_mx' : 'sem_mx';
    }
  }
  if (v.telefone_e164) {
    v.whatsapp_apto = true;
  }
}

stats.email_apto = [...validacoes.values()].filter(v => v.email_apto).length;
stats.telefone_apto = [...validacoes.values()].filter(v => v.whatsapp_apto).length;

return [{ json: { validacoes: [...validacoes.values()], stats } }];
